mapper.select:
SELECT customer_type, COUNT(1) as count
FROM dc_customer_information
WHERE del_flag = 0

    AND lawyer_id = #{lawyerId}


    AND customer_city = #{city}

GROUP BY customer_type

SELECT *
FROM dc_customer_information
WHERE del_flag = 0

    AND lawyer_id = #{userId}


    AND YEAR(create_time) = #{year}


    AND MONTH(create_time) = #{month}


    AND DAY(create_time) = #{day}

SELECT package_type, COUNT(1) as count
FROM dc_customer_information
WHERE del_flag = 0

    AND lawyer_id = #{lawyerId}


    AND customer_city = #{city}

GROUP BY package_type

SELECT * FROM dc_customer_information WHERE del_flag = 0 AND expire_date BETWEEN DATE_SUB(CURDATE(), INTERVAL 7 DAY) AND DATE_ADD(CURDATE(), INTERVAL 7 DAY)
AND lawyer_id = #{lawyerId}
AND customer_city = #{city}

SELECT *
FROM dc_customer_information
WHERE del_flag = 0
AND balance > 0

    AND lawyer_id = #{lawyerId}


    AND customer_city = #{city}

SELECT * FROM dc_customer_information WHERE id NOT IN ( SELECT customer_id FROM dc_customer_tracking WHERE del_flag = 0 AND tracking_time >= DATE_SUB( CURDATE(), INTERVAL 15 DAY )) AND id NOT IN ( SELECT customer_id FROM dc_customer_out_visit WHERE del_flag = 0 AND visit_time >= DATE_SUB( CURDATE(), INTERVAL 15 DAY )) AND id NOT IN ( SELECT customer_id FROM dc_insurance_case WHERE del_flag = 0 AND order_date >= DATE_SUB( CURDATE(), INTERVAL 15 DAY )) AND id NOT IN ( SELECT customer_id FROM dc_debt_case WHERE del_flag = 0 AND request_receive_time >= DATE_SUB( CURDATE(), INTERVAL 15 DAY )) AND id NOT IN ( SELECT customer_id FROM dc_customer_job_order WHERE del_flag = 0 AND create_time >= DATE_SUB( CURDATE(), INTERVAL 15 DAY )) AND id NOT IN ( SELECT customer_id FROM dc_case_tracking WHERE del_flag = 0 AND tracking_time >= DATE_SUB( CURDATE(), INTERVAL 15 DAY )) AND del_flag = 0 AND expire_date >= CURDATE()
AND lawyer_id = #{lawyerId}
AND customer_city = #{city}

SELECT
ci.*,
COALESCE(log_count_tbl.log_count, 0) as logCount
FROM dc_customer_information ci
LEFT JOIN (
SELECT customer_info_id, COUNT(*) as log_count
FROM dc_customer_information_log
WHERE del_flag = '0'
GROUP BY customer_info_id
) log_count_tbl ON ci.id = log_count_tbl.customer_info_id
WHERE ci.del_flag = '0'

    AND ${ew.sqlSegment}


    AND COALESCE(log_count_tbl.log_count, 0) >= #{minLogCount}


    AND COALESCE(log_count_tbl.log_count, 0) <= #{maxLogCount}


    AND COALESCE(log_count_tbl.log_count, 0) = #{logCount}

ORDER BY ci.create_time DESC
